import{_ as n,c as r,o as i,ae as a}from"./chunks/framework.CHDT0Kbg.js";const m=JSON.parse('{"title":"Häufige Fragen","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/faq.md","filePath":"de/guide/faq.md","lastUpdated":1795170900000}'),t={name:"de/guide/faq.md"};function s(o,e,d,h,c,l){return i(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="haufige-fragen" tabindex="-1">Häufige Fragen <a class="header-anchor" href="#haufige-fragen" aria-label="Permalink to &quot;Häufige Fragen&quot;">​</a></h1><p>Kurze Antworten zu Persim.</p><h3 id="ist-persim-kostenlos" tabindex="-1">Ist Persim kostenlos? <a class="header-anchor" href="#ist-persim-kostenlos" aria-label="Permalink to &quot;Ist Persim kostenlos?&quot;">​</a></h3><p>Die grundlegenden Browserfunktionen sind kostenlos nutzbar. Einige erweiterte Funktionen gibt es per In-App-Kauf; die kostenlose Version zeigt ein kleines Abzeichen in der Tab-Leiste.</p><h3 id="welche-betriebssysteme-werden-unterstutzt" tabindex="-1">Welche Betriebssysteme werden unterstützt? <a class="header-anchor" href="#welche-betriebssysteme-werden-unterstutzt" aria-label="Permalink to &quot;Welche Betriebssysteme werden unterstützt?&quot;">​</a></h3><p>Persim ist für macOS 12 oder neuer entwickelt und läuft auf Apple Silicon und Intel.</p><h3 id="werden-meine-daten-hochgeladen" tabindex="-1">Werden meine Daten hochgeladen? <a class="header-anchor" href="#werden-meine-daten-hochgeladen" aria-label="Permalink to &quot;Werden meine Daten hochgeladen?&quot;">​</a></h3><p>Nein. Verlauf, Lesezeichen, Sitzungen und Downloads bleiben lokal, ein Konto ist nicht nötig. Nur Funktionen wie die Aktualisierung eines Werbeblocker-Abonnements nutzen das Netz.</p><h3 id="wie-ubernehme-ich-lesezeichen-aus-einem-anderen-browser" tabindex="-1">Wie übernehme ich Lesezeichen aus einem anderen Browser? <a class="header-anchor" href="#wie-ubernehme-ich-lesezeichen-aus-einem-anderen-browser" aria-label="Permalink to &quot;Wie übernehme ich Lesezeichen aus einem anderen Browser?&quot;">​</a></h3><p>In Chrome oder Edge als HTML exportieren, dann im Persim-Lesezeichenmanager „HTML importieren“ wählen. Ordner und doppelte Links werden automatisch behandelt.</p><h3 id="wie-speichere-ich-ein-video" tabindex="-1">Wie speichere ich ein Video? <a class="header-anchor" href="#wie-speichere-ich-ein-video" aria-label="Permalink to &quot;Wie speichere ich ein Video?&quot;">​</a></h3><p>Medienfenster öffnen, erkanntes Video auswählen und herunterladen. Aufgeteilte Videos werden zu einer MP4 zusammengefügt.</p><h3 id="wie-andere-ich-die-sprache" tabindex="-1">Wie ändere ich die Sprache? <a class="header-anchor" href="#wie-andere-ich-die-sprache" aria-label="Permalink to &quot;Wie ändere ich die Sprache?&quot;">​</a></h3><p><code>persim://settings</code> → <strong>Allgemein</strong> → <strong>Sprache</strong>. 25 Sprachen stehen bereit; nach dem erneuten Öffnen des Fensters ist die Änderung sichtbar.</p><h3 id="noch-eine-frage" tabindex="-1">Noch eine Frage? <a class="header-anchor" href="#noch-eine-frage" aria-label="Permalink to &quot;Noch eine Frage?&quot;">​</a></h3><p>Schreibe an <strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong> und beschreibe, was du tun möchtest.</p>',16)])])}const p=n(t,[["render",s]]);export{m as __pageData,p as default};
